local LOG_PATH = "sleepy_log.txt"
local _log_buf = {}

local function _log_flush()
    pcall(function()
        if writefile then writefile(LOG_PATH, table.concat(_log_buf, "\n")) end
    end)
end

local function _log(tag, msg)
    local line = string.format("[%.2f] [%s] %s", tick(), tag, tostring(msg))
    _log_buf[#_log_buf+1] = line
    _log_flush()
end

-- Clear file cũ
pcall(function() if writefile then writefile(LOG_PATH, "") end end)

-- Wrap warn/print để cũng ghi file
local _realWarn  = warn
local _realPrint = print
getgenv().warn = function(...)
    local args, n = {...}, select("#", ...)
    local parts = {}
    for i = 1, n do parts[i] = tostring(args[i]) end
    local msg = table.concat(parts, "\t")
    _log("WARN", msg)
    return _realWarn(...)
end
getgenv().print = function(...)
    local args, n = {...}, select("#", ...)
    local parts = {}
    for i = 1, n do parts[i] = tostring(args[i]) end
    local msg = table.concat(parts, "\t")
    _log("PRINT", msg)
    return _realPrint(...)
end

