local function __b64_decode(s)
    -- try executor built-in trước (nhanh)
    if crypt and crypt.base64decode then return crypt.base64decode(s) end
    if crypt and crypt.base64 and crypt.base64.decode then return crypt.base64.decode(s) end
    if syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then return syn.crypt.base64.decode(s) end
    if base64_decode then return base64_decode(s) end
    if base64 and base64.decode then return base64.decode(s) end
    if Base64 and Base64.Decode then return Base64.Decode(s) end
    -- pure lua fallback (chậm)
    warn("[offline] using pure-lua base64 (slow, ~5s)")
    local tab = {}
    for i = 0, 63 do
        tab[("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):sub(i+1,i+1)] = i
    end
    s = s:gsub("[^A-Za-z0-9+/=]", "")
    local out, i, n = {}, 1, #s
    while i <= n do
        local a = tab[s:sub(i,i)]     or 0
        local b = tab[s:sub(i+1,i+1)] or 0
        local c = tab[s:sub(i+2,i+2)]
        local d = tab[s:sub(i+3,i+3)]
        out[#out+1] = string.char(a * 4 + math.floor(b / 16))
        if c then
            out[#out+1] = string.char((b % 16) * 16 + math.floor(c / 4))
            if d then
                out[#out+1] = string.char((c % 4) * 64 + d)
            end
        end
        i = i + 4
    end
    return table.concat(out)
end

