warn("[offline] all chunks decoded, patching filesystem...")

do
    local realReadfile = readfile
    local realIsfile   = isfile
    local realDelfile  = delfile
    local realMakefolder = makefolder
    local realWritefile  = writefile

    getgenv().readfile = function(path)
        local p = tostring(path)
        if __embedded[p] then return __embedded[p] end
        if realReadfile then return realReadfile(path) end
        error("readfile: file not found: " .. p)
    end
    getgenv().isfile = function(path)
        local p = tostring(path)
        if __embedded[p] then return true end
        if realIsfile then return realIsfile(path) end
        return false
    end
    getgenv().makefolder = function(path)
        if realMakefolder then pcall(realMakefolder, path) end
    end
    if not realDelfile then getgenv().delfile = function(_) end end
    getgenv().writefile = function(path, data)
        local p = tostring(path)
        if p:find("static_content") then
            __embedded[p] = data
            return
        end
        if realWritefile then return realWritefile(path, data) end
    end
end
warn("[offline] filesystem patched")

