-- Chỉ chặn HttpGet về v4_init để trả cache embedded (tránh fetch lại).
warn("[offline] HTTP auth: để luarmor gọi thật qua internet")

do
    local ok, mt = pcall(getrawmetatable, game)
    if ok and mt and setreadonly then
        local realHttpGet = game.HttpGet
        local oldIdx = mt.__index
        local oldNamecall = mt.__namecall
        setreadonly(mt, false)
        local fakeHttpGet = newcclosure(function(self, url, ...)
            -- CHỈ hook v4_init -> trả cache embedded (tránh re-fetch)
            if type(url) == "string" and url:find("v4_init") then
                return __embedded["static_content_170926/init-b1f104a87aa-noven.lua"]
            end
            return realHttpGet(self, url, ...)
        end)
        mt.__index = newcclosure(function(self, key)
            if key == "HttpGet" and self == game then return fakeHttpGet end
            return oldIdx(self, key)
        end)
        mt.__namecall = newcclosure(function(self, ...)
            local method = getnamecallmethod()
            if method == "HttpGet" and self == game then return fakeHttpGet(self, ...) end
            return oldNamecall(self, ...)
        end)
        setreadonly(mt, true)
        warn("[offline] HttpGet: chỉ chặn v4_init -> cache embedded")
    else
        warn("[offline] no getrawmetatable -> HttpGet NOT hooked")
    end
end

